#[test]
fn old_rust_jsonl_store_migrates() -> Result<()> {
    // An old Rust store layout: `.relay/{manifest.json, events/*.jsonl,
    // artifacts/}` built from the real corpus bytes.
    let fixture = Path::new(REPO_ROOT).join("tests/fixtures/cases/e2e-demo-run");
    let dir = tempfile::tempdir()?;
    let relay = dir.path().join(".relay");
    std::fs::create_dir_all(relay.join("events"))?;
    std::fs::copy(
        fixture.join("events.jsonl"),
        relay.join("events").join("0000000000000001-open.jsonl"),
    )?;
    copy_dir(&fixture.join("artifacts"), &relay.join("artifacts"))?;
    // A minimal manifest so the layout is discoverable; the reader only
    // needs the segments.
    std::fs::write(
        relay.join("manifest.json"),
        "{\"activeSegment\":\"0000000000000001-open.jsonl\",\"createdAt\":\"2026-10-13T00:00:01.000Z\",\"minReaderVersion\":\"0.2.0\",\"projectId\":\"prj_00000000-0000-4000-8000-000000000009\",\"storeVersion\":1}",
    )?;

    let before = snapshot(&dir.path().join(".relay"));
    let outcome = migrate::migrate(
        dir.path(),
        &LegacySource::JsonlStore {
            root: relay.clone(),
            artifacts_dir: relay.join("artifacts"),
        },
        &options(),
    )?;
    assert_source_untouched(&before, &snapshot(&dir.path().join(".relay")));

    let store = open_migrated(dir.path())?;
    let graph = store.project_graph()?;
    assert!(graph.goal().is_some());
    assert_eq!(outcome.report.legacy_events, 63);
    Ok(())
}

#[test]
fn failed_migration_leaves_the_original_active() -> Result<()> {
    // A corrupted legacy stream fails validation before anything is staged,
    // and the workspace keeps its original state.
    let fixture = Path::new(REPO_ROOT).join("tests/fixtures/cases/e2e-demo-run");
    let dir = tempfile::tempdir()?;
    let relay = dir.path().join(".relay");
    std::fs::create_dir_all(&relay)?;
    let mut text = std::fs::read_to_string(fixture.join("events.jsonl"))?;
    // Corrupt one payload byte so reference validation fails.
    text = text.replacen(
        "Demonstrate the Relay workflow",
        "Demonstrate the Relay workflow!",
        1,
    );
    std::fs::write(relay.join("events.jsonl"), text)?;
    copy_dir(&fixture.join("artifacts"), &relay.join("artifacts"))?;

    let before = snapshot(&dir.path().join(".relay"));
    let error = migrate::migrate(
        dir.path(),
        &LegacySource::EventsFile {
            file: relay.join("events.jsonl"),
            artifacts_dir: relay.join("artifacts"),
        },
        &options(),
    )
    .err()
    .map(|e| e.to_string())
    .unwrap_or_default();
    assert!(
        error.contains("invalid") || error.contains("failed reference validation"),
        "{error}"
    );
    // No new store, no staging leftovers, source untouched.
    assert!(!dir.path().join(".relay-graph").exists());
    assert_source_untouched(&before, &snapshot(&dir.path().join(".relay")));
    Ok(())
}

#[test]
fn staged_graph_validates_before_the_switch() -> Result<()> {
    // Extract from the real corpus, then prove the staged facts fold: the
    // `migrate` entry point already gates on this; assert it directly.
    let dir = demo_workspace()?;
    let relay = dir.path().join(".relay");
    let (facts, report) = migrate::plan(&LegacySource::EventsFile {
        file: relay.join("events.jsonl"),
        artifacts_dir: relay.join("artifacts"),
    })?;
    assert!(!facts.is_empty());
    assert!(report.facts_emitted == facts.len() as u64);
    // The planned stream folds through the domain graph on its own.
    let graph = relay_domain::ProjectGraph::from_facts(&facts)?;
    assert!(graph.goal().is_some());
    // Every fact is a known kind at a known version.
    use relay_store::FactValidator as _;
    for fact in &facts {
        let input = relay_store::to_input(fact)?;
        assert!(
            relay_store::fact::DomainFactValidator
                .validate_input(&input)
                .is_ok()
        );
    }
    Ok(())
}

#[test]
fn rollback_restores_the_previous_store() -> Result<()> {
    // A workspace that already has a fact store: the migration retains it
    // as a backup, and rollback swaps it back.
    let dir = demo_workspace()?;
    let relay = dir.path().join(".relay");

    // Seed an existing (older) fact store with one fact.
    let project = relay_domain::ProjectId::parse("prj_previous")?;
    {
        let existing = relay_store::GraphFactStore::create(
            dir.path(),
            &project,
            relay_store::Integrity::Checksums,
            options().store,
        )?;
        existing.append(&[DomainFact::ProjectCreated { project }])?;
    }
    let previous_timeline = {
        let existing = relay_store::GraphFactStore::open_read_only(dir.path(), options().store)?;
        existing.read_timeline()?
    };
    assert_eq!(previous_timeline.len(), 1);

    let outcome = migrate::migrate(
        dir.path(),
        &LegacySource::EventsFile {
            file: relay.join("events.jsonl"),
            artifacts_dir: relay.join("artifacts"),
        },
        &options(),
    )?;
    let backup = outcome
        .previous_store_backup
        .clone()
        .ok_or("expected a previous-store backup")?;
    assert!(backup.is_dir());

    // The migrated store is live and different from the previous one.
    let migrated = open_migrated(dir.path())?;
    assert!(migrated.revision()?.get() > 1);

    // Rollback: the migrated store is retained aside, the backup restored.
    let rolled = migrate::rollback(dir.path(), &backup)?;
    assert!(
        rolled.is_dir(),
        "the migrated store is retained, never deleted"
    );
    let restored = relay_store::GraphFactStore::open_read_only(dir.path(), options().store)?;
    assert_eq!(restored.read_timeline()?, previous_timeline);
    // The legacy source is still untouched.
    assert!(relay.join("events.jsonl").is_file());
    Ok(())
}

