#[test]
fn default_source_detects_legacy_shapes() -> Result<()> {
    let dir = demo_workspace()?;
    let relay = dir.path().join(".relay");
    assert!(matches!(
        migrate::default_source(dir.path()),
        Some(LegacySource::JsonlStore { .. })
    ));
    // A state.db takes precedence when present.
    let connection = Connection::open(relay.join("state.db"))?;
    connection.execute_batch("CREATE TABLE events (id TEXT);")?;
    drop(connection);
    assert!(matches!(
        migrate::default_source(dir.path()),
        Some(LegacySource::StateDb { .. })
    ));
    Ok(())
}
